// Minimal faithful re-implementation of Python argparse for this exact spec:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=int, required=True)
//   parser.add_argument('--c', type=int, required=True)
// Usage: parseArgs(process.argv.slice(2), prog) -> {a: string, b: int, c: int}

const OPTIONS = [
  { name: '--a', dest: 'a', metavar: 'A', type: 'str' },
  { name: '--b', dest: 'b', metavar: 'B', type: 'int' },
  { name: '--c', dest: 'c', metavar: 'C', type: 'int' },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function error(prog, msg) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${msg}\n`);
  process.exit(2);
}

// Python repr() of a string.
function pyRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + quote;
}

// argparse treats a token as option-like if it starts with '-' and does not
// look like a negative number (this parser has no negative-number options).
function looksLikeOption(token) {
  if (!token.startsWith('-') || token === '-') return false;
  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false; // negative number
  return true;
}

// Python int(): optional surrounding whitespace, optional +/- sign, digits only.
function parseInt_(optName, raw, prog) {
  const trimmed = raw.trim();
  if (/^[+-]?\d+$/.test(trimmed)) {
    return parseInt(trimmed, 10);
  }
  error(prog, `argument ${optName}: invalid int value: ${pyRepr(raw)}`);
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(prog);
      process.exit(0);
    }

    let optName = null;
    let inlineValue = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        optName = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      } else {
        optName = token;
      }
    }

    const opt = optName !== null ? OPTIONS.find((o) => o.name === optName) : null;
    if (opt) {
      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          error(prog, `argument ${opt.name}: expected one argument`);
        }
        raw = next;
        i += 1;
      }
      values[opt.dest] = opt.type === 'int' ? parseInt_(opt.name, raw, prog) : raw;
    } else {
      extras.push(token);
    }
    i += 1;
  }

  // Required-argument check happens before the unrecognized-argument check.
  const missing = OPTIONS.filter((o) => !(o.dest in values)).map((o) => o.name);
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b, c: values.c };
}
